# Every idea, as a player would say it, with the comparison that tests it. report.py runs them.
# where: 'bet' (first to act or after a check, flop), 'face' (facing a flop bet), or a turn spot.
# key: the number the idea is about; sign: the direction the saying predicts for A minus B.
import pandas as pd
NP = lambda x: (x.klass == 'no pair') & x.nodraw
D = lambda x: x.klass == 'no pair'
K = lambda *n: (lambda x: x.klass.isin(n))
PAIRS = ['top pair', 'middle pair', 'bottom pair']; WEAK = ['middle pair', 'bottom pair', 'pocket below top']
med = lambda x, c: x.groupby('key')[c].transform('median')
I = []
def idea(id, where, say, why, A, B, key, sign, match=None, min_w=0.5): I.append(dict(id=id, where=where, say=say, why=why, A=A, B=B, key=key, sign=sign, match=match, min_w=min_w))
# ---- flop, betting
for k in ['top pair', 'overpair']:
    idea(f'bdf-{k}-size', 'bet', f'{k.capitalize()} with a backdoor flush draw bets smaller', 'it has more to gain from seeing the turn, and a small bet is the one it can call a raise after', lambda x, k=k: (x.klass == k) & x.bdf & x.nodraw, lambda x, k=k: (x.klass == k) & ~x.bdf & x.nodraw, 'size_pos', -1)
    idea(f'bdf-{k}-check', 'bet', f'{k.capitalize()} with a backdoor flush draw checks more', 'the same', lambda x, k=k: (x.klass == k) & x.bdf & x.nodraw, lambda x, k=k: (x.klass == k) & ~x.bdf & x.nodraw, 'bet', -1)
    idea(f'bdf-{k}-worth', 'bet', f'{k.capitalize()} with a backdoor flush draw makes more than its equity says', 'the extra turns it can continue on', lambda x, k=k: (x.klass == k) & x.bdf & x.nodraw, lambda x, k=k: (x.klass == k) & ~x.bdf & x.nodraw, 'over_real', 1)
idea('bdf-air-bet', 'bet', 'Unpaired hands with a backdoor flush draw bet more than those without (same equity)', 'more turns to keep betting on', lambda x: NP(x) & x.bdf, lambda x: NP(x) & ~x.bdf, 'bet', 1, match='e')
idea('bds-air-bet', 'bet', 'Unpaired hands with a backdoor straight draw bet more than those without (same equity)', 'more turns to keep betting on', lambda x: NP(x) & x.bds & ~x.bdf, lambda x: NP(x) & (x.ways == 0) & ~x.bdf, 'bet', 1, match='e')
idea('weak-pair-bdf-bet', 'bet', 'Middle and bottom pairs with a backdoor flush draw bet more', 'protection now, and a turn to barrel', lambda x: K(*WEAK)(x) & x.bdf & x.nodraw, lambda x: K(*WEAK)(x) & ~x.bdf & x.nodraw, 'bet', 1)
idea('acehigh-check', 'bet', 'Ace high checks more than lower unpaired hands', 'it has showdown value to protect; the lower hands have none', lambda x: NP(x) & (x.hi == 12), lambda x: NP(x) & (x.hi < 12), 'bet', -1)
idea('weakest-bet', 'bet', 'The weakest unpaired hands bet more than the better ones', 'no showdown value to lose', lambda x: NP(x) & (x.e < med(x, 'e')), lambda x: NP(x) & (x.e >= med(x, 'e')), 'bet', 1)
idea('blocker-bet', 'bet', 'Unpaired hands bet more when their cards make him fold more (same equity)', 'a bluff works when he folds', lambda x: NP(x) & (x.hefolds > med(x, 'hefolds')), lambda x: NP(x) & (x.hefolds <= med(x, 'hefolds')), 'bet', 1, match='e')
idea('gutshot-bet', 'bet', 'A gutshot bets more than a no-draw hand of the same equity', 'four clean outs when called', lambda x: D(x) & x.gut & ~x.fd, NP, 'bet', 1, match='e')
idea('nutfd-bet', 'bet', 'The nut flush draw bets more than lower flush draws', 'it is never drawing dead and can call a raise', lambda x: D(x) & x.fd & (x.fd_nut == 0), lambda x: D(x) & x.fd & (x.fd_nut > 0), 'bet', 1)
idea('fd-oesd-bet', 'bet', 'Flush draws bet more than open-enders', '', lambda x: D(x) & x.fd & ~x.oesd, lambda x: D(x) & x.oesd & ~x.fd, 'bet', 1)
idea('pairdraw-bet', 'bet', 'A pair with a draw bets more than the pair alone', 'equity when called on top of showdown value', lambda x: K(*PAIRS)(x) & (x.fd | x.oesd), lambda x: K(*PAIRS)(x) & x.nodraw, 'bet', 1)
idea('kicker-bet', 'bet', 'Top pair with a top kicker bets more than top pair with a weak one', 'it is ahead of the top pairs that call', lambda x: (x.klass == 'top pair') & (x.kick_rank <= 1), lambda x: (x.klass == 'top pair') & (x.kick_rank > 1), 'bet', 1)
idea('kicker-size', 'bet', 'Top pair with a top kicker bets bigger', 'the same', lambda x: (x.klass == 'top pair') & (x.kick_rank <= 1), lambda x: (x.klass == 'top pair') & (x.kick_rank > 1), 'size_pos', 1)
idea('lowover-bet', 'bet', 'Low overpairs bet more than high ones', 'more turn cards hurt them', lambda x: (x.klass == 'overpair') & (x.hi - x.board_top <= 2), lambda x: (x.klass == 'overpair') & (x.hi - x.board_top > 2), 'bet', 1)
idea('aces-slow', 'bet', 'Aces check more than other overpairs', 'no card hurts them, and they block his calls least', lambda x: (x.klass == 'overpair') & (x.hi == 12), lambda x: (x.klass == 'overpair') & (x.hi < 12), 'bet', -1)
idea('exposed-toppair', 'bet', 'Top pair that loses more on bad turns bets more (same equity)', 'protection', lambda x: (x.klass == 'top pair') & (x.down > med(x[x.klass == 'top pair'], 'down').reindex(x.index)), lambda x: (x.klass == 'top pair') & (x.down <= med(x[x.klass == 'top pair'], 'down').reindex(x.index)), 'bet', 1, match='e')
idea('exposed-weakpair', 'bet', 'A weak pair that loses more on bad turns bets more (same equity)', 'protection', lambda x: K(*WEAK)(x) & (x.down > med(x[K(*WEAK)(x)], 'down').reindex(x.index)), lambda x: K(*WEAK)(x) & (x.down <= med(x[K(*WEAK)(x)], 'down').reindex(x.index)), 'bet', 1, match='e')
idea('underpair-bet', 'bet', 'A pocket pair below the board bets less than a pair made with the board (same equity)', 'two outs against five', lambda x: K('underpair', 'pocket below top')(x), lambda x: K('middle pair', 'bottom pair')(x), 'bet', -1, match='e')
idea('topset-slow', 'bet', 'Top set checks more than lower sets', 'it holds the cards he would call with', lambda x: (x.klass == 'set') & (x.hi == x.board_top), lambda x: (x.klass == 'set') & (x.hi < x.board_top), 'bet', -1, min_w=0.2)
# ---- flop, facing a bet
for k, label in [('middle pair', 'Middle pair'), ('pocket below top', 'A pocket pair below top pair'), ('underpair', 'An underpair'), ('no pair', 'An unpaired hand')]:
    idea(f'bdf-{k}-continue', 'face', f'{label} with a backdoor flush draw folds less than without (same equity)', 'more turns it can continue on', lambda x, k=k: (x.klass == k) & x.bdf & x.nodraw, lambda x, k=k: (x.klass == k) & ~x.bdf & x.nodraw, 'fold', -1, match='e')
idea('bdf-toppair-call', 'face', 'Top pair with a backdoor flush draw raises less', 'it wants to see the turn', lambda x: (x.klass == 'top pair') & x.bdf & x.nodraw, lambda x: (x.klass == 'top pair') & ~x.bdf & x.nodraw, 'raise', -1)
idea('bdf-overpair-call', 'face', 'An overpair with a backdoor flush draw raises less', 'it wants to see the turn', lambda x: (x.klass == 'overpair') & x.bdf & x.nodraw, lambda x: (x.klass == 'overpair') & ~x.bdf & x.nodraw, 'raise', -1)
idea('bds-air-continue', 'face', 'An unpaired hand with a backdoor straight draw folds less (same equity)', 'more turns it can continue on', lambda x: NP(x) & x.bds & ~x.bdf, lambda x: NP(x) & (x.ways == 0) & ~x.bdf, 'fold', -1, match='e')
idea('acehigh-continue', 'face', 'Ace high folds less than lower unpaired hands', 'it beats his bluffs', lambda x: NP(x) & (x.hi == 12), lambda x: NP(x) & (x.hi < 12), 'fold', -1)
idea('underpair-fold', 'face', 'A pocket pair below the board folds more than a pair made with the board (same equity)', 'two outs against five, and most turns hurt', lambda x: K('underpair', 'pocket below top')(x), lambda x: K('middle pair', 'bottom pair')(x), 'fold', 1, match='e')
idea('gutshot-continue', 'face', 'A gutshot folds less than a no-draw hand of the same equity', 'outs to the nuts and implied odds', lambda x: D(x) & x.gut & ~x.fd, NP, 'fold', -1, match='e')
idea('gutshot-raise', 'face', 'A gutshot raises more than a no-draw hand of the same equity', 'a cheap bluff that can still win', lambda x: D(x) & x.gut & ~x.fd, NP, 'raise', 1, match='e')
idea('weakdraw-raise', 'face', 'Gutshots raise more than open-enders', 'weak draws can raise and fold; good draws do not want to be re-raised', lambda x: D(x) & x.gut & ~x.fd, lambda x: D(x) & x.oesd & ~x.fd, 'raise', 1)
idea('fd-raise', 'face', 'Flush draws raise more than gutshots', '', lambda x: D(x) & x.fd, lambda x: D(x) & x.gut & ~x.fd, 'raise', 1)
idea('nutfd-call', 'face', 'The nut flush draw raises less than lower flush draws', 'showdown value and implied odds: it prefers to call', lambda x: D(x) & x.fd & (x.fd_nut == 0), lambda x: D(x) & x.fd & (x.fd_nut > 0), 'raise', -1)
idea('pairdraw-call', 'face', 'A draw with a pair raises less than a draw without', 'showdown value: no reason to turn it into a bluff', lambda x: (x.fd | x.oesd) & K(*PAIRS)(x), lambda x: (x.fd | x.oesd) & D(x), 'raise', -1)
idea('kicker-raise', 'face', 'Top pair with a top kicker raises more than with a weak one', '', lambda x: (x.klass == 'top pair') & (x.kick_rank <= 1), lambda x: (x.klass == 'top pair') & (x.kick_rank > 1), 'raise', 1)
idea('kickerover-call', 'face', 'Top pair with a kicker over the board raises less than with a kicker under it', 'low top pairs with big kickers are still good on most turns; top pair with a low kicker is not', lambda x: (x.klass == 'top pair') & x.kick_over, lambda x: (x.klass == 'top pair') & ~x.kick_over & x.kick.notna(), 'raise', -1)
idea('lowover-raise', 'face', 'Low overpairs raise more than high ones', 'protection', lambda x: (x.klass == 'overpair') & (x.hi - x.board_top <= 2), lambda x: (x.klass == 'overpair') & (x.hi - x.board_top > 2), 'raise', 1)
idea('topset-call', 'face', 'Top set raises less than lower sets', 'it holds the cards he would continue with', lambda x: (x.klass == 'set') & (x.hi == x.board_top), lambda x: (x.klass == 'set') & (x.hi < x.board_top), 'raise', -1, min_w=0.2)
idea('exposed-raise', 'face', 'Top pair and overpairs that lose more on bad turns raise more (same equity)', 'protection', lambda x: K('top pair', 'overpair')(x) & (x.down > med(x[K('top pair', 'overpair')(x)], 'down').reindex(x.index)), lambda x: K('top pair', 'overpair')(x) & (x.down <= med(x[K('top pair', 'overpair')(x)], 'down').reindex(x.index)), 'raise', 1, match='e')
# ---- turn
for where, name in [('barrel', 'betting the turn after the flop bet was called'), ('delayed', 'in position after the flop checked through'), ('probe', 'out of position after the flop checked through')]:
    idea(f'{where}-fd', where, f'Flush draws bet, no-draw hands give up ({name})', 'equity when called', lambda x: D(x) & x.fd, NP, 'bet', 1)
    idea(f'{where}-gut', where, f'A gutshot bets more than a no-draw hand of the same equity ({name})', 'outs when called', lambda x: D(x) & x.gut & ~x.fd, NP, 'bet', 1, match='e')
    idea(f'{where}-blocker', where, f'Among no-draw hands, the ones whose cards make him fold more bet more ({name})', 'a bluff works when he folds', lambda x: NP(x) & (x.hefolds > med(x, 'hefolds')), lambda x: NP(x) & (x.hefolds <= med(x, 'hefolds')), 'bet', 1, match='e')
    idea(f'{where}-flushcard', where, f'Among no-draw hands, holding the ace or king of the flush suit bets more ({name})', 'it takes away the draws that call', lambda x: NP(x) & (x.blocker_fd == True), lambda x: NP(x) & (x.blocker_fd == False), 'bet', 1, match='e')
    idea(f'{where}-acehigh', where, f'Ace high bets less than lower no-draw hands ({name})', 'showdown value', lambda x: NP(x) & (x.hi == 12), lambda x: NP(x) & (x.hi < 12), 'bet', -1)
    idea(f'{where}-pairdraw', where, f'A weak pair with a draw bets more than the pair alone ({name})', 'it can bet as a draw and still has a pair when checked back', lambda x: K(*WEAK)(x) & ~x.nodraw, lambda x: K(*WEAK)(x) & x.nodraw, 'bet', 1)
    idea(f'{where}-toppairdraw', where, f'Top pair with a draw bets more than top pair alone ({name})', '', lambda x: (x.klass == 'top pair') & ~x.nodraw, lambda x: (x.klass == 'top pair') & x.nodraw, 'bet', 1)
    idea(f'{where}-kicker', where, f'Top pair with a top kicker bets more ({name})', 'ahead of the top pairs that call', lambda x: (x.klass == 'top pair') & (x.kick_rank <= 1), lambda x: (x.klass == 'top pair') & (x.kick_rank > 1), 'bet', 1)
    idea(f'{where}-nutfd', where, f'The nut flush draw bets less than lower flush draws ({name})', 'ace high can win unimproved, and it does not want to be raised off the nuts', lambda x: D(x) & x.fd & (x.fd_nut == 0), lambda x: D(x) & x.fd & (x.fd_nut > 0), 'bet', -1)
    idea(f'{where}-lowover', where, f'Low overpairs bet more than high ones ({name})', 'protection', lambda x: (x.klass == 'overpair') & (x.hi - x.board_top <= 2), lambda x: (x.klass == 'overpair') & (x.hi - x.board_top > 2), 'bet', 1)
# ---- second wave: redraws, kickers on weak pairs, overcards
TP = lambda x: x.klass == 'top pair'
idea('upside-toppair-bet', 'bet', 'Top pair with more to gain on the turn bets more (same equity)', 'a redraw to two pair or better makes it happy to build the pot', lambda x: TP(x) & x.nodraw & (x.up > med(x[TP(x) & x.nodraw], 'up').reindex(x.index)), lambda x: TP(x) & x.nodraw & (x.up <= med(x[TP(x) & x.nodraw], 'up').reindex(x.index)), 'bet', 1, match='e')
idea('upside-toppair-size', 'bet', 'Top pair with more to gain on the turn bets bigger (same equity)', 'the same', lambda x: TP(x) & x.nodraw & (x.up > med(x[TP(x) & x.nodraw], 'up').reindex(x.index)), lambda x: TP(x) & x.nodraw & (x.up <= med(x[TP(x) & x.nodraw], 'up').reindex(x.index)), 'size_pos', 1, match='e')
idea('weakpair-kicker-bet', 'bet', 'A middle or bottom pair with a kicker over the board bets more than with a low kicker', 'three outs to a two pair that beats top pair', lambda x: K('middle pair', 'bottom pair')(x) & x.kick_over, lambda x: K('middle pair', 'bottom pair')(x) & ~x.kick_over & x.kick.notna(), 'bet', 1)
idea('weakpair-kicker-continue', 'face', 'A middle or bottom pair with a kicker over the board folds less than with a low kicker', 'three outs to a two pair that beats top pair, and an overcard', lambda x: K('middle pair', 'bottom pair')(x) & x.kick_over, lambda x: K('middle pair', 'bottom pair')(x) & ~x.kick_over & x.kick.notna(), 'fold', -1)
idea('weakpair-acekicker-continue', 'face', 'A middle or bottom pair with an ace kicker folds less than with another kicker (same equity)', 'the ace is an out that wins, and it blocks top pair with an ace', lambda x: K('middle pair', 'bottom pair')(x) & (x.kick == 12), lambda x: K('middle pair', 'bottom pair')(x) & (x.kick < 12), 'fold', -1, match='e')
idea('overcards-continue', 'face', 'Two overcards fold less than one or none (no pair, no draw)', 'six outs', lambda x: NP(x) & (x.over == 2), lambda x: NP(x) & (x.over < 2), 'fold', -1)
idea('overcards-bet', 'bet', 'Two overcards bet more than one or none (no pair, no draw)', 'six outs when called', lambda x: NP(x) & (x.over == 2), lambda x: NP(x) & (x.over < 2), 'bet', 1)
idea('bdf-two-cards', 'face', 'An unpaired hand whose backdoor flush uses both its cards folds less than one using a single card', 'a hidden flush that gets paid, against one anyone can see', lambda x: NP(x) & x.bdf & x.bdf_two, lambda x: NP(x) & x.bdf & ~x.bdf_two, 'fold', -1, match='e')
idea('bdf-nut-continue', 'face', 'An unpaired hand with a nut backdoor flush draw folds less than with a low one (same equity)', 'the flush it makes is the best one', lambda x: NP(x) & x.bdf & (x.bdf_nut == 0), lambda x: NP(x) & x.bdf & (x.bdf_nut > 1), 'fold', -1, match='e')
idea('bdf-air-raise', 'face', 'An unpaired hand with a backdoor flush draw raises more than without (same equity)', 'the bluff-raise that can pick up a draw on the turn', lambda x: NP(x) & x.bdf, lambda x: NP(x) & ~x.bdf, 'raise', 1, match='e')
idea('blocker-raise', 'face', 'Among unpaired hands, holding the ace or king of the flush suit raises more (same equity)', 'it takes the nut draw out of his hands that continue', lambda x: NP(x) & (x.blocker_fd == True), lambda x: NP(x) & (x.blocker_fd == False), 'raise', 1, match='e')
idea('toppair-bdf-fold', 'face', 'Top pair with a backdoor flush draw folds less', '', lambda x: TP(x) & x.bdf & x.nodraw, lambda x: TP(x) & ~x.bdf & x.nodraw, 'fold', -1)
idea('worth-bdf-air', 'bet', 'An unpaired hand with a backdoor flush draw makes more than its equity says (against one without)', 'turns it can continue on', lambda x: NP(x) & x.bdf, lambda x: NP(x) & ~x.bdf, 'over_real', 1, match='e')
idea('worth-underpair', 'bet', 'A pocket pair below the board makes less of its equity than a pair made with the board (same equity)', 'two outs, and most turns hurt', lambda x: K('underpair', 'pocket below top')(x), lambda x: K('middle pair', 'bottom pair')(x), 'over_real', -1, match='e')
idea('worth-acehigh', 'bet', 'Ace high makes less of its equity than a draw of the same equity', 'its equity is showdown equity that bets fold out', NP, lambda x: D(x) & (x.fd | x.oesd | x.gut), 'over_real', -1, match='e')
idea('worth-kicker', 'bet', 'Top pair with a top kicker makes more than its equity says against weaker kickers (same equity)', 'it wins the big pots against other top pairs', lambda x: TP(x) & (x.kick_rank <= 1), lambda x: TP(x) & (x.kick_rank > 1), 'over_real', 1, match='e')
